import { siteUrl } from "../(seo)/seo-pages";

export type BlogContentBlock =
  | { type: "paragraphs"; paragraphs: readonly string[] }
  | { type: "list"; items: readonly string[] }
  | { type: "table"; headers: readonly string[]; rows: readonly (readonly string[])[] }
  | { type: "subheading"; heading: string };

export type BlogPost = {
  slug: string;
  title: string;
  description: string;
  category: string;
  author: string;
  published: boolean;
  publishedAt: string;
  modifiedAt: string;
  readingTime: string;
  intro: string;
  sections: readonly { id: string; heading: string; content: readonly BlogContentBlock[] }[];
  relatedSlugs: readonly string[];
  internalLinks: readonly { label: string; href: string }[];
  cta: string;
};

const p = (...paragraphs: string[]): BlogContentBlock => ({ type: "paragraphs", paragraphs });
const list = (...items: string[]): BlogContentBlock => ({ type: "list", items });
const table = (headers: string[], rows: string[][]): BlogContentBlock => ({ type: "table", headers, rows });
type BlogSection = BlogPost["sections"][number];

const links = {
  journal: { label: "Trading journal for Indian traders", href: "/trading-journal-india" },
  product: { label: "See the TradeLore product workflow", href: "/product" },
  analytics: { label: "Explore trading performance analytics", href: "/features/trading-analytics" },
  replay: { label: "Review trades with trade replay", href: "/features/trade-replay" },
  notes: { label: "Explore the trading journal feature", href: "/features/trading-journal" },
};

const detailedSections: Record<string, readonly BlogSection[]> = {
  "best-trading-journal-india": [
    { id: "buying-checklist", heading: "A practical buying checklist", content: [p("Before choosing a journal, write down the path from execution to review. Which source is authoritative for fills? How will you handle a partially filled order? Where will you store the original plan? Can you filter by strategy, instrument, date and time without rebuilding the sheet? These questions reveal more than a long feature list."), p("For Indian F&O traders, check whether the tool keeps the contract identity intact: underlying, expiry, strike, option type, side, quantity and lot size. An equity-only journal may still be useful, but it should not be presented as a complete derivatives workflow. For any broker integration, run a small reconciliation with one known session before importing months of history."), list("Export or retain the broker's source report for reconciliation.", "Check how duplicate fills and partial exits are represented.", "Confirm whether charges are imported, calculated or entered separately.", "Test the review workflow on a losing trade as well as a winning trade.", "Read the data-retention and deletion terms before connecting an account.")] },
    { id: "spreadsheet-to-software", heading: "When to move beyond Excel or Google Sheets", content: [p("A spreadsheet is often the right first journal because it makes every field visible and costs nothing beyond the tool you already use. The maintenance burden grows when you copy fills, reconcile IDs, preserve screenshots, update formulas, and create the same weekly report repeatedly. At that point, automation is valuable only if it reduces errors without hiding the underlying data."), p("TradeLore is positioned as one workflow option for this transition. Its repository includes broker adapters, CSV import, a shared trade-order pipeline, matching, journal screens, reports and trade replay. That describes the implementation; it is not an independent ranking or a promise that the product fits every trader. Compare the actual workflow and current pricing before choosing."), p("[SOURCE REQUIRED: verify current competitor features, integrations, pricing and security terms before publication]")] },
    { id: "decision-process", heading: "A low-risk way to choose", content: [p("Use a three-stage test. First, import or enter ten representative trades, including one partial exit and one trade with a correction. Second, reconcile the count, direction, quantity and net result with the broker source. Third, complete a weekly review without adding a new column or manual workaround. If the tool survives this test, decide whether the time saved justifies its cost."), p("Do not select a journal because its dashboard looks impressive. Select the one that helps you answer a recurring question: which setups did I follow, which behaviours cost me, and what will I test next week?")] },
  ],
  "trading-journal-template-india": [
    { id: "build-workbook", heading: "Build the workbook in layers", content: [p("Start with a Trades sheet that stores one completed trade or one leg, depending on the structure you choose. Add a stable trade ID, leg ID and strategy tag before adding charts. A separate Lists sheet can hold allowed markets, strategies, mistake tags and emotional tags; data validation prevents spelling variations from splitting your reports."), p("Keep a Raw Import sheet if you paste broker data. Never overwrite it with cleaned values. Use a Clean Trades sheet for normalised fields, then a Review sheet for pivots and charts. This separation gives you an audit trail when a total changes and prevents a dashboard formula from silently changing the source record."), list("Freeze the header row and filter by date.", "Use ISO-style dates or a single consistent date format.", "Record timestamps in IST when the source provides them.", "Keep charges as a separate input rather than hiding them in gross P&L.", "Back up the workbook before changing formulas.")] },
    { id: "formula-edge-cases", heading: "Formula edge cases to handle", content: [p("For a long trade, price P&L is (exit − entry) × quantity. For a short trade, it is (entry − exit) × quantity. If a position is scaled, calculate each leg first and then sum the legs. Do not multiply a premium difference by an assumed lot size when quantity already contains the traded units."), p("Realised R-multiple needs a positive planned-risk denominator. If the stop was not defined before entry, leave R blank rather than inventing a risk number after the result. If the position was adjusted, preserve both original planned risk and the adjustment note. For a multi-leg strategy, keep gross and net results at both leg and strategy level."), p("Avoid putting current brokerage, STT, GST, stamp duty or exchange rates directly into a template without a source and effective date. Charges vary by product, broker and regulation: [SOURCE REQUIRED: current applicable Indian trading charges and official source].")] },
    { id: "review-routine", heading: "Turn the sheet into a review routine", content: [p("After each session, complete the execution fields while the sequence is fresh. At the end of the week, filter for missing screenshots, missing reasons and untagged mistakes before reading the P&L. Then compare strategy, time window, direction, holding time and average loss. Finish with one written change for the next week."), p("A template is successful when it is completed consistently, not when it contains the most columns. If copying and reconciling broker data takes longer than the review itself, that is the point at which an automated import workflow becomes worth evaluating.")] },
  ],
  "how-to-maintain-fno-trading-journal": [
    { id: "pretrade-protocol", heading: "Use a pre-trade protocol", content: [p("Before sending an F&O order, write the underlying view, contract selected, direction, entry trigger, invalidation, planned stop, target, quantity and maximum rupee risk. For options, record whether the premium is the price you are buying or selling and whether the position is part of a spread. For futures, record the contract and lot size so a price move can be translated into rupees."), p("Separate what was known before entry from what became visible after entry. This prevents hindsight from turning a favourable outcome into a supposedly obvious trade. A one-line thesis is enough if it is specific: the condition, the trigger and the invalidation should be testable later."), list("Record the planned exit before the order whenever practical.", "Record expected event or expiry exposure without predicting the result.", "State whether the position is intraday or carried.", "Mark a strategy ID for every leg of a multi-leg trade.")] },
    { id: "futures-options-differences", heading: "Futures and options need different review fields", content: [table(["Review area", "Futures", "Options"], [["Contract identity", "Underlying, expiry, lot size", "Underlying, strike, expiry, CE/PE, lot size"], ["Price field", "Futures price", "Premium"], ["Risk note", "Price move × quantity or multiplier", "Premium movement plus position structure"], ["Management", "Roll, reduce or exit", "Partial exits, spread legs, exercise/expiry context"], ["Review question", "Did the contract move as expected?", "Did the thesis and option structure behave as expected?"]]), p("The journal should not force both products into one generic ‘buy price’ field. Keep product-specific fields while using common fields for thesis, charges, mistake, emotion and lesson.")] },
    { id: "multi-leg-review", heading: "Review a multi-leg strategy as one decision and many executions", content: [p("Give the strategy a parent ID and each leg a leg ID. Record the entry and exit of every leg, but also write one combined thesis, planned maximum risk, intended adjustment rule and combined exit reason. A single leg can look profitable while the spread or hedge is losing overall."), p("When a leg is opened or closed at a different time, record the sequence. Note whether the change was planned, triggered by a rule, or made reactively. Review net P&L and charges at strategy level, then inspect each leg for slippage, sizing and execution quality."), p("Use the same approach for an anonymised NIFTY or BANKNIFTY example: no trade recommendation, only a record of the contract, the plan, the fills and the lesson.")] },
    { id: "daily-weekly-workflow", heading: "A repeatable daily and weekly workflow", content: [p("Daily: write the plan, import or enter fills, match legs, complete exit reason and add one screenshot or chart note. Weekly: group by strategy, underlying, expiry type, time window and mistake tag. Investigate trades where the planned risk, lot size or contract metadata is missing before trusting the summary."), p("A journal does not make a derivative position safer by itself. It makes the difference between planned risk and actual behaviour easier to see. This article is educational and not financial advice.")] },
  ],
  "calculate-net-trading-pnl-india": [
    { id: "calculation-order", heading: "Calculate in the right order", content: [p("First calculate gross price P&L from the actual direction, quantity and execution prices. Then add or subtract any realised components that belong to the trade, such as funding or other product-specific adjustments, and finally subtract the charges shown on the broker source. Keep the sign convention consistent: a cost should reduce the result."), p("For a long trade, gross price P&L is (exit − entry) × quantity. For a short trade, it is (entry − exit) × quantity. With multiple fills, calculate a weighted average only when the fills belong to the same instrument and side; otherwise retain the individual executions and let the matching logic determine the completed trade."), p("Never use a current charge rate from memory. Brokerage, exchange charges, STT, GST, stamp duty and other statutory items can change and can differ by market and product. [SOURCE REQUIRED: current applicable Indian trading charges and official source]")] },
    { id: "reconcile-contract-note", heading: "Reconcile the result with the contract note", content: [p("A journal is a review layer, not the official financial record. When the journal and broker statement disagree, compare the trade date, instrument, quantity, average prices, order legs, charges and treatment of open positions. A mismatch may come from a partial fill, an overnight position, a corporate-action adjustment, a different charge grouping or a trade that has not been closed."), list("Keep the original contract note or broker report.", "Compare gross and net figures separately.", "Record whether charges were imported or entered manually.", "Do not silently overwrite the source number; add a reconciliation note.", "Use the same date range and settlement convention in every report.")] },
    { id: "cost-sensitivity", heading: "Use cost sensitivity in reviews", content: [p("A strategy with small average winners can be highly sensitive to fixed costs and turnover. Compare gross expectancy with net expectancy, then compare the number of trades and average charge per trade. This does not prove that a strategy is good or bad; it shows how much of the observed result depends on execution cost assumptions."), p("If you trade different markets, keep the market and product visible in the analysis. Do not transfer one segment's charge treatment to another. Charges vary by broker, market and regulation, so verify them before using the numbers for a financial decision.")] },
  ],
  "broker-pnl-report-vs-trading-journal": [
    { id: "map-fields", heading: "Map the broker record to the journal record", content: [table(["Broker-side evidence", "Journal question"], [["Order and fill IDs", "Which executions belong to this decision?"], ["Instrument and quantity", "Was the intended size and contract traded?"], ["Average price and time", "Did entry and exit follow the plan?"], ["Charges and net result", "What did the decision produce after cost?"], ["No reasoning field", "What was the thesis, mistake or lesson?"]]), p("Start the journal with broker evidence and add your own context beside it. Do not edit a broker fill to make it agree with a memory-based note. If the source is incomplete, flag the field and investigate before using the trade in a detailed performance conclusion.")] },
    { id: "review-loop", heading: "A complete review loop", content: [p("After the market closes, import or reconcile the trade data. Match fills into completed trades. Add the planned setup, risk, exit reason and screenshot. Then filter the week by strategy, time of day, holding period, mistake and rule adherence. Finally, replay one trade and write the smallest rule change that the evidence supports."), p("This workflow separates record keeping from interpretation. The broker report tells you whether the execution happened; the journal tells you whether the execution matched the decision you intended to make. Both are useful, but they answer different questions."), p("TradeLore's public product pages describe broker import, journaling, trade replay and reports. Verify the current product and pricing before making a purchasing decision.")] },
    { id: "reconciliation-checklist", heading: "Reconciliation checklist", content: [list("Do the source and journal have the same number of fills?", "Are partial exits and reversals represented correctly?", "Are the direction, quantity and average price plausible?", "Are gross P&L, charges and net P&L clearly separated?", "Have you kept the official broker report for records?", "Did the journal add a reason that the broker report cannot show?")] },
  ],
  "import-zerodha-trades-trading-journal": [
    { id: "requirements", heading: "What you need before connecting Zerodha", content: [p("The current TradeLore workflow expects a Zerodha Personal API app with an API key, API secret and redirect URL. The settings page displays the redirect URL that belongs in the app configuration. Save the credentials in TradeLore before clicking Connect Zerodha; the login route checks that credentials exist and that the server-side integration is configured."), p("[SOURCE REQUIRED: verify current Zerodha/Kite Connect app creation, redirect-URL and Personal API instructions before publishing exact third-party navigation]") , list("A TradeLore account with the required active entitlement.", "Your own Zerodha Personal API credentials.", "The exact redirect URL shown in TradeLore settings.", "A current Zerodha session that can approve the connection.")] },
    { id: "connection-step-by-step", heading: "Step by step: connect, authorise and return", content: [p("1. Open TradeLore's Zerodha settings and open the sync help if needed. 2. Save the API key and API secret. 3. Click Connect Zerodha. TradeLore generates a random state value, stores it in an HTTP-only short-lived cookie, and redirects you to the Kite login URL. 4. Complete the broker authorisation. 5. Zerodha returns a request token and state to the callback. TradeLore checks both values, exchanges the request token using the API key, secret and checksum, encrypts the returned access token, stores the broker identity and redirects you back with a connection status."), p("If the callback is missing a request token or the state cookie does not match, the connection is rejected. If the app is not enabled for the user, the UI reports that separately. These checks protect the connection flow; they do not replace careful credential handling.")] },
    { id: "sync-details", heading: "What happens when you sync", content: [p("The sync requests Zerodha trade fills and ignores incomplete rows without a trade ID, order ID, symbol, positive quantity or positive average price. It loads instrument metadata for any NFO, BFO or MCX exchange present in the fill set, then normalises symbol, exchange, segment, expiry, strike, lot size, instrument type, trade time, order ID, trade ID, side, quantity and price."), p("Normalised fills receive a stable identifier using the Zerodha user, order ID and trade ID. They pass through the shared trade-order sync pipeline, which persists the orders and matches them into completed trades. The sync returns imported orders, total orders, total trades and diagnostic counts such as raw fills, unique order IDs and collapsed fills."), p("The implementation fetches the current trade endpoint rather than promising unlimited historical history. [SOURCE REQUIRED: verify current Zerodha trade-history and export behaviour]")] },
    { id: "segments-and-metadata", heading: "Equity, F&O, BFO and MCX metadata", content: [p("For NSE and BSE fills, the normalised segment is equity. For NFO, BFO and MCX fills, TradeLore attempts to enrich the fill with the relevant instrument master. That enrichment can supply expiry, strike, lot size, instrument type and, for MCX, additional commodity metadata. If the metadata request fails, the fill may still be normalised with the fields available from the source, but the review should flag missing contract details."), p("Do not infer an option strike, expiry or lot size from a symbol string in the article or in a manual review. Use the source data and instrument metadata that actually arrived.")] },
    { id: "reconnect-and-troubleshoot", heading: "Reconnect, duplicates and troubleshooting", content: [table(["Symptom", "What to check"], [["Reconnect required", "The access token is short-lived or expired; connect again before syncing."], ["Credentials required", "API key/secret were not saved or the server is not configured."], ["No trades imported", "Check the broker account, date/session, identifiers and source response."], ["Wrong contract fields", "Check NFO/BFO/MCX instrument metadata availability."], ["Totals look duplicated", "Compare stable trade IDs, order IDs and the shared pipeline totals."], ["Callback failed", "Check redirect URL, app enablement and state-cookie completion."]]), p("TradeLore does not place, modify or cancel orders. Use a read-only Personal API setup and revoke credentials from the broker if you believe they were exposed.")] },
  ],
  "import-dhan-trades-trading-journal": [
    { id: "requirements", heading: "What you need before connecting Dhan", content: [p("The current Dhan workflow uses a DhanHQ app with Client ID, API key, API secret and the redirect and postback URL shown in TradeLore settings. The settings page instructs you to create credentials, save all three values, then connect through Dhan. TradeLore stores the app credentials and access token; the Dhan password, PIN and TOTP remain on Dhan."), p("[SOURCE REQUIRED: verify current DhanHQ app creation, redirect and postback instructions before publishing exact third-party navigation]") ] },
    { id: "connection-step-by-step", heading: "Step by step: Dhan consent connection", content: [p("1. Open Dhan settings in TradeLore and copy the displayed redirect URL into both the Dhan Redirect URL and Postback URL fields. 2. Save the Client ID, API key and API secret in TradeLore. 3. Click Connect Dhan. The server creates a consent application using the Client ID and app credentials, then redirects you to Dhan's consent login. 4. Complete the Dhan login and TOTP flow. 5. Dhan returns a token ID to TradeLore. The callback verifies that the connection was started, consumes the token, checks that the returned Dhan client ID matches the saved broker user ID, encrypts the access token and records its expiry."), p("If the token ID is missing, the flow was not started, credentials are missing, or the client ID does not match, the callback redirects back with a clear failure status. This is why a copied credential from a different Dhan account can fail even when the secret itself is valid.")] },
    { id: "sync-details", heading: "What TradeLore imports from Dhan", content: [p("The sync calls Dhan's trade endpoint with the saved client ID and decrypted access token. It normalises valid rows with exchange trade ID, order ID, exchange order ID, side, exchange segment, product type, symbol, security ID, traded quantity, traded price, and the most useful available timestamp. For derivatives it also preserves expiry, option type and strike when the source supplies them."), p("A Dhan record is accepted only when it has the identifiers, symbol, positive quantity and positive price needed to create a usable trade order. The normalised order enters the shared sync and trade-matching pipeline. The response reports imported trades, imported orders, total orders and total matched trades; it does not guarantee a particular historical look-back range."), p("[SOURCE REQUIRED: verify current Dhan historical trade response and retention window]")] },
    { id: "options-and-errors", heading: "Options, duplicates and common errors", content: [p("The repository test covers an NFO options record with CE type, quantity and price, so options metadata can be represented when Dhan returns it. Do not fill missing strike, expiry or lot-size values from a symbol guess. A valid record may still require a review note if the source omits a field important to your strategy."), list("Save all three credentials before connecting.", "Reconnect when the access token expires or Dhan rejects it.", "Compare imported totals with the Dhan trade book for one session.", "Use order ID, exchange order ID and exchange trade ID to investigate duplicates.", "Check the segment and timestamp fields before comparing day or time reports.")] },
    { id: "after-sync", heading: "After the first sync", content: [p("Choose one known day with equity and, if applicable, one derivatives trade. Compare symbol, direction, quantity, price, time and contract fields against the Dhan source. Then open the matched TradeLore trade, add the thesis, risk, exit reason and lesson, and only after that import a wider period. This makes a connection problem easier to isolate from a journaling problem.")] },
  ],
  "import-upstox-trades-trading-journal": [
    { id: "requirements", heading: "What you need before connecting Upstox", content: [p("The current Upstox workflow uses an Upstox developer app with API key, API secret and a redirect URL. TradeLore settings displays the redirect URL that must be placed in the app. Save those credentials before clicking Connect Upstox; the login route checks server configuration and saved credentials before generating the authorisation URL."), p("[SOURCE REQUIRED: verify current Upstox developer-console, app-creation and redirect-URL instructions before publishing exact third-party navigation]") ] },
    { id: "connection-step-by-step", heading: "Step by step: Upstox OAuth connection", content: [p("1. Open Upstox settings in TradeLore and copy the displayed redirect URL. 2. Create or open the Upstox app and set that redirect URL. 3. Save the API key and secret in TradeLore. 4. Click Connect Upstox. TradeLore generates a random state, stores it in short-lived HTTP-only cookies, and redirects to Upstox with the client ID, redirect URI and state. 5. Approve the login. 6. The callback checks the returned code and state, exchanges the code with the client ID, secret and redirect URL, encrypts the access token, saves the broker identity and returns to TradeLore."), p("A missing code, missing state or state mismatch stops the callback. If the token exchange is rejected, reconnect after checking the redirect URL and app credentials.")] },
    { id: "historical-sync", heading: "Historical sync: segments, pages and retention", content: [p("The sync requests Upstox historical trades for EQ, FO, COM and CD segments. It uses a six-month retained window in the current implementation and paginates each segment with a page size of 500 until the API reports the final page. It then combines all segments before normalising them."), p("The normaliser keeps trade ID, trade date, exchange, segment, option type, quantity, price, expiry, strike, instrument name, symbol and transaction type where supplied. Because the current Upstox historical response exposes a date rather than an intraday timestamp in the normaliser, TradeLore sets the stored trade time to midnight for that record. Do not promise time-of-day analysis from this import without verifying the current source fields."), p("The six-month window is an implementation detail and can change. [SOURCE REQUIRED: verify current Upstox historical-trade retention and API limits]")] },
    { id: "troubleshooting", heading: "Common errors and reconciliation", content: [table(["Problem", "Action"], [["Reconnect or 401/403", "Reconnect Upstox to refresh the stored access token."], ["Missing segment", "Check the source response and the requested EQ/FO/COM/CD segment."], ["Missing trade", "Check date window, page metadata and broker history."], ["Wrong timestamp expectation", "Remember the current normaliser uses the trade date at midnight."], ["Duplicate concern", "Compare the stable user/date/trade ID used by the normaliser."], ["Incomplete row", "Check trade ID, symbol, date, side, positive quantity and price."]]), p("Validate one day and one segment first. Once totals and fields match the source, sync the remaining retained window and review the resulting trades.")] },
  ],
  "import-angel-one-trades-trading-journal": [
    { id: "requirements", heading: "What you need before connecting Angel One", content: [p("The current Angel One workflow is not an OAuth redirect flow. It expects an Angel One SmartAPI key and a JWT token generated through the broker's login process. TradeLore settings explicitly says it does not store the client PIN/password or TOTP secret; it stores the SmartAPI key and JWT token needed for read-only trade-book requests."), p("[SOURCE REQUIRED: verify current Angel One SmartAPI app creation, login and JWT instructions before publishing exact third-party navigation]") ] },
    { id: "connection-step-by-step", heading: "Step by step: save access and sync", content: [p("1. Create or open the SmartAPI app and copy its API key. 2. Use the current Angel One SmartAPI login process with your client code, PIN/password and TOTP to obtain a JWT token. 3. Open TradeLore Angel One settings and paste the API key and JWT token into Save Angel One Access. 4. Click Save credentials. 5. Click Sync Angel One. The server sends the key and bearer token to the trade-book endpoint and returns the sync result."), p("The current flow does not require a redirect URL. If the JWT is rejected or expires, generate a fresh token and save it again. Treat the token like a credential: do not paste it into a public note, screenshot or support ticket.")] },
    { id: "imported-data", heading: "What gets imported and matched", content: [p("The adapter reads the Angel One trade book and accepts rows with an order ID, fill ID, symbol, transaction type, positive fill size, positive fill price and a usable fill or update time. It preserves exchange, product type, expiry, option type, strike, symbol token and instrument type where the source provides them."), p("For NSE and BSE rows, the normaliser maps the segment to EQ. Other exchange values are preserved as the segment. Option type CE or PE is retained when present; a generic option instrument type without a clear option type should not be treated as proof of the exact contract. Stable broker, user, order and trade IDs are used before the shared pipeline matches the trade."), p("[SOURCE REQUIRED: verify current Angel One trade-book response fields and historical availability]")] },
    { id: "errors-security", heading: "Errors, duplicates and security", content: [list("API key or JWT missing: save both values before syncing.", "401/403 response: generate and save a fresh JWT token.", "No imported rows: compare required identifiers and positive price/quantity.", "Unexpected totals: reconcile order ID and fill ID with the trade book.", "Sensitive token exposure: revoke or replace the token through Angel One.")] },
    { id: "first-sync", heading: "Validate the first Angel One sync", content: [p("Use a known session containing one equity trade and, if relevant, one derivatives trade. Compare exchange, symbol, side, quantity, price and timestamp before reviewing P&L. Then add the plan and exit reason in TradeLore. Only after this check should you sync a broader period; the adapter reads the broker trade book and does not promise unlimited historical backfill.")] },
  ],
  "delta-exchange-india-trading-journal": [
    { id: "requirements", heading: "What you need before connecting Delta", content: [p("The current Delta settings flow expects an API key and API secret. Its help panel instructs you to create a key with read or data permissions, avoid trading and withdrawal permissions, save both values in TradeLore, and then use either API sync or CSV import. If you use IP restrictions at Delta, the current TradeLore server IP requirements must be verified before relying on an allowlist."), p("[SOURCE REQUIRED: verify current Delta Exchange India API-key permissions, IP allowlist rules and account terminology]")] },
    { id: "api-sync-step-by-step", heading: "Step by step: API sync", content: [p("1. Create a read-only/data API key in Delta. 2. Save the key and secret in TradeLore. 3. Click Sync Delta. TradeLore signs each request with an HMAC-SHA256 signature over the uppercase method, current timestamp, request path, query string and body. 4. It requests fills in pages of 100, follows the returned cursor, loads or fetches product metadata, converts valid fills into trade orders, fetches wallet transactions for funding enrichment, and sends the result through the shared matching pipeline."), p("The sync stores a cursor so later runs can continue from the last page. It also has a process-local lock to reject a second sync for the same account while one is active. That lock is not a substitute for a distributed lock across multiple server instances; the implementation comment identifies that limit."), p("[SOURCE REQUIRED: verify current Delta API endpoint names, signature rules and pagination behaviour]")] },
    { id: "csv-and-fields", heading: "API fields and CSV fallback", content: [p("A valid API fill needs a fill ID, symbol, positive size, positive price and BUY or SELL side. Product metadata supplies contract type, notional type, contract value, quote asset, settlement asset, expiry and settlement information. The normalised order retains order ID, fill ID, commission, commission asset and liquidity role where present."), p("TradeLore's Delta settings also exposes Import Delta CSV. The upload is routed through the shared import endpoint, so validate the imported count and matched trade count against the source export. [SOURCE REQUIRED: verify the current Delta CSV column format and export instructions]") ] },
    { id: "positions-fees-funding", heading: "Review positions, fees, funding and settlement", content: [p("Review fills rather than assuming an order equals a position. Multiple fills can open, reduce, reverse or partially close a long or short position. Use product metadata to distinguish perpetual, futures and option contract types where the source supplies them. Do not describe a product as a perpetual or an option solely from a symbol without checking metadata."), p("Commission is stored as a fee amount with a fee asset. Wallet transactions are filtered for funding transactions, normalised by transaction ID, date, product and asset, and assigned once to the latest same-day/product trade bucket to avoid double counting. That bucket assignment is a deliberate simplification: inspect the raw funding transaction when exact attribution matters."), p("Settlement currency, leverage, contract value and funding treatment can materially change interpretation. Verify current Delta terminology and contract specifications before publishing or using a report for a financial decision.")] },
    { id: "troubleshooting", heading: "Delta troubleshooting", content: [table(["Error or symptom", "Likely check"], [["Invalid API key", "Re-enter credentials or revoke and recreate the read-only key."], ["Signature expired", "Check server clock and current API timestamp requirements."], ["Signature mismatch", "Check API secret, path, query and body signing inputs."], ["IP not whitelisted", "Review the key's allowlist and production server requirements."], ["Rate limit", "Wait for the returned reset time before retrying."], ["Missing product", "Refresh the product cache or verify the symbol exists."], ["CSV mismatch", "Compare source columns, fills, fees and duplicate IDs."]]) ] },
  ],
  "trading-journal-metrics": [
    { id: "metric-workflow", heading: "Build a metric review in layers", content: [p("Begin with the complete sample: date range, number of trades, market, strategy tags and cost treatment. Then read outcome metrics such as net P&L and profit factor. Next read distribution metrics such as average winner, average loser, R-multiple and drawdown. Only then segment by setup, instrument or time of day."), p("Every metric needs a denominator and a population. Report trade count beside win rate, average beside median where outliers are possible, and gross beside net when costs matter. A dashboard without its sample definition can make a small or selective result look more stable than it is."), list("Keep the raw trades available behind every aggregate.", "Freeze the date range when comparing two reviews.", "Mark whether open trades are excluded.", "Do not compare gross figures with net figures as if they were equivalent.")] },
    { id: "interpretation", heading: "Questions each metric can answer", content: [table(["Metric group", "Good question", "Bad conclusion"], [["Net P&L / drawdown", "What did this sample return and give back?", "This will repeat."], ["Win rate / averages", "How are wins and losses distributed?", "A high win rate is enough."], ["Profit factor / expectancy", "Does the observed distribution have positive average value?", "Positive expectancy is guaranteed."], ["MFE / MAE", "What path did trades take before exit?", "The chart proves a new stop."], ["Setup / time", "Where should I investigate further?", "This time is universally best."]]) ] },
    { id: "data-quality", heading: "Data-quality checks before trusting a metric", content: [p("Check direction, quantities, partial exits, charges, duplicate IDs, timestamps, contract metadata and missing journal tags. A single malformed quantity can distort average winner, and a missing exit can distort holding time. When a result looks surprising, open the largest contributors rather than changing the formula first."), p("Metrics are descriptive evidence about a chosen sample. They are not investment advice, a performance guarantee or proof that a strategy will work in a different market regime.")] },
  ],
  "profit-factor-vs-win-rate": [
    { id: "calculate-by-hand", heading: "Calculate both from the same trade set", content: [p("Write the winning results and losing results in separate columns, after deciding whether the figures are gross or net. Win rate is the count of positive closed trades divided by all closed trades. Profit factor is the sum of positive results divided by the absolute sum of negative results. A breakeven trade must have a documented rule for whether it belongs in the denominator."), p("Do not calculate profit factor from average win and average loss unless the counts are also included. Do not compare a daily win rate with a monthly profit factor unless both use the same population and cost treatment. Keep the trade count visible beside every metric.")] },
    { id: "expectancy-connection", heading: "Connect the metrics to expectancy", content: [p("Win rate becomes useful when combined with the size of wins and losses. If a strategy wins 40% of the time with a ₹300 average win and loses 60% of the time with an ₹80 average loss, expectancy is ₹72 before charges. If the loss distribution includes a rare outlier, the average loss and drawdown need to be inspected rather than hidden behind the win rate."), p("Profit factor is a ratio, so it can look high in a tiny sample or after one exceptional trade. Use it beside expectancy, sample size, maximum drawdown and the actual trade list.")] },
    { id: "review-protocol", heading: "A review protocol for the two metrics", content: [list("Set the date range and include only closed trades.", "Confirm whether numbers are gross or net.", "Record total trades, wins, losses and breakevens.", "Inspect average and median win and loss.", "Open the largest winner and loser.", "Repeat the calculation by strategy only after tag quality is acceptable.")] },
  ],
  "trading-expectancy-explained": [
    { id: "worked-calculation", heading: "Calculate expectancy step by step", content: [p("Suppose 40 of 100 trades win and the average winning trade is ₹300. The winning contribution is 0.40 × ₹300 = ₹120. The remaining 60 trades lose an average of ₹80, so the losing contribution is 0.60 × ₹80 = ₹48. Expectancy is ₹120 − ₹48 = ₹72 per trade before any omitted charges."), p("If the same sample had a ₹20 average charge per trade, the simple net estimate would be ₹52, but only if the ₹20 is consistently measured across the same trades. Do not mix a gross average win with a net average loss."), p("A negative sample works the same way: 65% wins at ₹100 and 35% losses at ₹250 gives ₹65 − ₹87.50 = −₹22.50 per trade.")] },
    { id: "segment-method", heading: "Segment expectancy without fooling yourself", content: [p("Create separate groups for strategy, instrument and time of day only when the group has a meaningful number of comparable trades. For each group, show trade count, win probability, average win, average loss, net P&L and drawdown. A small group can be a hypothesis, not a conclusion."), p("The same trade can belong to more than one grouping, but the underlying result must not be counted twice in the overall sample. If a multi-leg strategy is reviewed as one decision, use the combined result consistently rather than mixing leg-level and strategy-level expectancy.")] },
    { id: "what-it-cannot-do", heading: "What expectancy cannot tell you", content: [p("Expectancy does not describe the order of wins and losses, the size of the worst drawdown, liquidity, slippage or the likelihood of the next trade. It is a historical average based on recorded assumptions. Use it to identify what to investigate and what data to collect next, not to forecast a guaranteed income.")] },
  ],
  "mfe-mae-trading": [
    { id: "measurement-method", heading: "Choose a measurement convention", content: [p("For a long trade, MFE can be measured as the highest observed price minus entry and MAE as the lowest observed price minus entry. For a short trade, the favourable and adverse directions reverse. Decide whether the observation uses candle high/low, tick data, mark price or executable bid/ask data, then keep that convention consistent."), p("If the source only contains completed fills and no price path, the journal cannot reconstruct exact MFE or MAE without additional chart or market data. Mark the field as unavailable rather than creating a value from the exit alone.")] },
    { id: "chart-review", heading: "Read the chart together with the table", content: [p("For each trade, plot entry at zero, MAE below zero and MFE above zero, then mark the exit. A cluster of stopped trades with similar MAE may suggest a question about stop placement. A cluster of exits far below MFE may suggest a question about management. Neither pattern proves that moving a stop or target would have improved results."), p("Use the trade chart to inspect the path: gap, spread, volatility, partial exit and re-entry can make a single number misleading. Keep the raw data and the review note together.")] },
    { id: "scaling-example", heading: "Scaling in and out example", content: [table(["Leg", "Quantity", "Entry", "Exit", "Review issue"], [["Initial", "50", "100", "115", "MFE belongs to initial size"], ["Add", "25", "108", "115", "Different cost basis"], ["Partial exit", "40", "115", "118", "Path differs by leg"], ["Final exit", "35", "115", "112", "Combined trade hides leg outcomes"]]), p("For this structure, calculate leg-level excursions and a combined-position excursion only if the convention is documented. Do not compare a scaled trade with a single-entry trade without explaining the difference.")] },
  ],
  "r-multiple-risk-reward-ratio": [
    { id: "set-risk-before-entry", heading: "Set planned risk before entry", content: [p("Planned risk is not whatever the trade eventually lost. It is the rupee amount defined before entry from entry, stop, quantity, lot size and any multiplier. Record the original stop even if you later move it; add a separate field for the change and its reason."), p("Planned reward is the result at the intended target under the same size assumptions. Planned risk-reward is a planning ratio. It says nothing about the probability of reaching the target or the quality of the execution.")] },
    { id: "four-scenarios", heading: "How partial exits change realised R", content: [p("A full stop at a ₹500 planned risk is −1R. A full target that returns ₹1,000 is +2R. If half the position exits at +2R and the remaining half exits at 0R, the combined result is about +1R before charges. If the trader exits the whole position early at ₹150 on ₹500 planned risk, the result is +0.3R. These are accounting examples, not recommendations."), p("When quantity, stop or target changes after entry, preserve the original planned fields and record the management event. Otherwise the journal can make a trade look more disciplined than it was.")] },
    { id: "compare-trades", heading: "Compare trades fairly", content: [p("Rupee P&L alone rewards larger position size. R-multiple normalises the result by planned risk, which helps compare a small equity trade with a larger F&O trade. It still does not erase product differences, liquidity, gap risk, charges or the quality of the risk estimate."), list("Compare net R with net P&L when costs matter.", "Keep one convention for multi-leg strategies.", "Report the number of trades behind an average R.", "Inspect the full distribution, not only the mean.")] },
  ],
  "weekly-trading-review-process": [
    { id: "prepare-data", heading: "Prepare before the 30-minute review", content: [p("Do not spend the review rebuilding the data. Complete journal fields after each session, keep strategy and mistake tags consistent, and make sure imported trades have been matched. At the start of the weekly review, note the date range, number of trades and whether all charges are included."), p("If data is incomplete, use the first few minutes to identify what is missing, not to draw conclusions from a partial report. A clean smaller sample is more useful than a large sample with unknown gaps.")] },
    { id: "deep-questions", heading: "Questions for each checkpoint", content: [table(["Checkpoint", "Questions"], [["Net P&L", "Was the result gross or net? What was the largest contributor?"], ["Strategy", "Which tags have enough observations to compare?"], ["Best / worst trade", "Was the outcome and execution quality aligned?"], ["Mistakes", "Which action repeated and what did it cost?"], ["Sizing", "Did quantity match the written plan?"], ["Time", "Did time-of-day effects survive strategy controls?"], ["Next week", "What one observable behaviour changes?"]]) ] },
    { id: "tradelore-workflow", heading: "Suggested TradeLore workflow", content: [p("Use the current app flow as a sequence: import or sync the broker data, review the matched trades, complete pre-market and post-trade journal fields, open reports for strategy and time breakdowns, replay one representative trade, and record the next rule in your journal or playbook. Keep the workflow short enough to repeat."), p("The review is for process learning. It does not promise profitability and does not replace the broker statement or a risk plan.")] },
  ],
  "best-time-to-trade-journal-analysis": [
    { id: "tagging-rules", heading: "Define time windows before analysing", content: [p("Choose fixed windows that do not move to fit the result. For example, define the first 15 minutes from the market open, a morning block, a midday block and the final hour using one timezone. Record the actual session date and instrument so expiry-day and weekday comparisons are possible."), p("Do not compare a morning equity sample with a final-hour options sample and call it a time effect. First control for instrument, strategy, direction, expiry and position size. If the app has only date-level timestamps for a source, do not imply it can support intraday timing analysis for that source.")] },
    { id: "analysis-sequence", heading: "Analyse the sample in sequence", content: [list("Start with trade count and missing timestamps.", "Compare net P&L, average loss and expectancy.", "Review rule adherence and mistake tags.", "Split by instrument and strategy.", "Check expiry day and weekday separately.", "Open the underlying trades before changing your schedule.")] },
    { id: "example-interpretation", heading: "Interpret the example carefully", content: [p("If the first 15-minute window shows a loss across eight trades, the useful conclusion is ‘investigate entry quality, spread and sizing in this sample’, not ‘never trade the open’. If the morning group is positive across twenty trades, the next step is to collect more comparable trades and check whether strategy mix explains the difference."), p("Time-of-day analysis describes your recorded process under a particular market regime. It is not a universal rule or a prediction.")] },
  ],
  "how-to-track-trading-mistakes": [
    { id: "define-tags", heading: "Define tags so two reviews mean the same thing", content: [p("A mistake tag should describe an observable action and a rule it violated. ‘FOMO’ might mean entering without the planned trigger because price was moving; ‘late entry’ might mean entering after the trigger had already passed. Keep those definitions separate so the same behaviour is not counted twice."), table(["Tag", "Operational definition", "Evidence"], [["Oversizing", "Quantity exceeded the written size rule", "Planned versus actual quantity"], ["Moving stop-loss", "Stop was widened without a prewritten rule", "Original and revised stop"], ["Outside the plan", "Trade had no matching setup or permission", "Plan and trade tag"], ["Early exit", "Exit occurred before the rule or invalidation", "Planned and actual exit reason"]]) ] },
    { id: "measure-impact", heading: "Measure frequency and impact separately", content: [p("Count how often a mistake occurred, sum its net P&L impact, and calculate its average impact per tagged trade. A common small mistake may cost more overall than a rare large mistake. Also compare tagged trades with untagged trades, because the tag may be correlated with a particular strategy or time window rather than being the only cause."), p("Avoid assigning causation from one result. A rule-breaking win is still a rule break, while a rule-following loss is not automatically a mistake. The purpose is behavioural evidence, not self-criticism.")] },
    { id: "one-change", heading: "Run a one-change experiment", content: [p("Choose one recurring action, write a pre-trade check that would catch it, and review the tag at the end of the next week. Examples: a size confirmation before order entry, a maximum daily-loss stop, or a written invalidation before the trade. Change one thing so you can tell whether the behaviour changed."), p("This is a journaling workflow, not mental-health or medical advice.")] },
  ],
  "trading-psychology-journal": [
    { id: "state-vs-action", heading: "Separate state from action", content: [p("Record the emotional state before entry using a small, repeatable scale or tag, then record the action separately. ‘High stress’ is a state; ‘increased size despite the plan’ is an action. This distinction lets the review ask whether the state coincided with a different decision without turning a trading note into a diagnosis."), list("Before entry: confidence, stress, fear, FOMO and intended size.", "During management: hesitation, impulsive change, frustration or calm execution.", "After exit: response to loss, response to a win and rule adherence.", "End of session: whether the emotional note changed future behaviour.")] },
    { id: "compare-data", heading: "Compare emotional tags with the right metrics", content: [p("Group emotional tags against expectancy, average loss, trade frequency, strategy, holding time, sizing and net P&L. Always show the number of tagged trades. A result such as ‘FOMO-tagged trades had shorter holding times in 12 observations’ is a useful observation; ‘FOMO causes losses’ is too strong for a small journal sample."), p("Check whether an emotional tag is actually a proxy for another variable. Stress may appear mostly in expiry trades, and confidence may appear after a winning streak. Segment carefully before changing a process.")] },
    { id: "safe-boundaries", heading: "Set safe boundaries for the journal", content: [p("Keep the journal descriptive and private. Do not diagnose yourself or another trader from tags, and do not use the article as a substitute for professional support. If trading or reviewing feels unsafe or overwhelming, pause and seek appropriate support outside the app. The journal should help you make a clear process decision, not intensify distress.")] },
  ],
  "how-to-review-options-trade-example": [
    { id: "full-record", heading: "Full fictional trade record", content: [table(["Field", "Recorded value"], [["Context", "Fictional intraday conditional bullish setup"], ["Instrument", "NIFTY 25,000 CE"], ["Expiry", "26 Jun 2026"], ["Entry", "₹120 for 75 units"], ["Stop / target", "₹95 / ₹170"], ["Planned risk", "₹1,875"], ["Execution", "50 units out at ₹150; 25 units out at ₹138"], ["Gross P&L", "₹1,950"], ["Charges", "[CHARGES PLACEHOLDER]"], ["Net P&L", "₹1,950 − [CHARGES PLACEHOLDER]"], ["MFE / MAE", "+₹42 / −₹10 per option"], ["Lesson", "Predefine partial-exit management"]]) ] },
    { id: "review-questions", heading: "Review the trade in four passes", content: [p("Pass one is thesis: what condition was present and what would invalidate it? Pass two is risk: was quantity compatible with planned risk, and was the stop recorded before entry? Pass three is execution: did the fills, partial exits and timestamps match the plan? Pass four is behaviour: did emotion, haste or a rule violation change management?"), p("The same trade can be a good execution with a negative result, or a poor execution with a positive result. Keep those judgements separate. A screenshot or replay should support the note rather than replace the written explanation."), p("This is a fictional educational example and not a trade recommendation.")] },
    { id: "repeat-change", heading: "What to repeat and what to change", content: [table(["Keep", "Change"], [["Written invalidation before entry", "Define the partial-exit rule before sending the order"], ["Quantity matched one lot", "Record the exact management trigger"], ["Review MFE and MAE", "Do not treat a winning result as proof of the thesis"], ["Separate gross and net result", "Replace the charges placeholder with the contract note"]]), p("The right lesson is specific enough to check in the next trade review. Avoid converting one fictional example into a strategy or market prediction.")] },
  ],
};

const article = (post: Omit<BlogPost, "author" | "published" | "publishedAt" | "modifiedAt"> & { published?: boolean }): BlogPost => ({
  ...post,
  sections: [...post.sections, ...(detailedSections[post.slug] || [])],
  author: "TradeLore",
  published: post.published ?? true,
  publishedAt: "2026-07-22",
  modifiedAt: "2026-07-22",
});

