export const publishedBlogPosts = blogPosts.filter((post) => post.published);
export function getPublishedBlogPost(slug: string) { return publishedBlogPosts.find((post) => post.slug === slug); }
export function blogUrl(slug?: string) { return `${siteUrl}/blog${slug ? `/${slug}` : ""}`; }
